/*
 * Diagrams for the academy, plotted from the formulas rather than drawn.
 *
 * Every curve here is generated by sampling the same functions the analyser runs on, so a figure
 * cannot say something the maths does not. The impermanent-loss curve is LP.analyze.ilV2, the
 * capital-efficiency curve is LP.analyze.capitalEfficiency, and the cost curve is built from the
 * two components the execution panel models. If one of those functions changed, the pictures
 * would change with it.
 *
 * The labelled points are checked, not placed by eye: the chapter prose claims a 2x move costs
 * 5.72% and a 4x range gives exactly 2x efficiency, and the markers are positioned by evaluating
 * the function at those inputs.
 *
 * SVG specifics worth knowing: colours come from the theme tokens so both palettes work, every
 * drawn shape sets an explicit fill, and the viewBox leaves room for the outermost labels so
 * nothing clips.
 */
window.LP = window.LP || {};

LP.academyFigures = (function () {

  const W = 640, H = 300;                    // viewBox, with room for axis labels
  const M = { l: 54, r: 18, t: 18, b: 42 };  // margins inside it
  const PW = W - M.l - M.r;
  const PH = H - M.t - M.b;

  const fmt = (v, d) => (Math.round(v * Math.pow(10, d)) / Math.pow(10, d)).toFixed(d);

  /** Shared chrome: frame, grid, axis labels. */
  function frame(opts) {
    const { xTicks, yTicks, xLabel, yLabel } = opts;
    const grid = [];

    for (const t of yTicks) {
      const y = M.t + PH - t.p * PH;
      grid.push(`<line x1="${M.l}" y1="${y.toFixed(1)}" x2="${M.l + PW}" y2="${y.toFixed(1)}"
        stroke="var(--line)" stroke-width="1" fill="none"/>`);
      grid.push(`<text x="${M.l - 9}" y="${(y + 4).toFixed(1)}" text-anchor="end"
        font-size="11" fill="var(--muted)" font-family="var(--mono)">${t.label}</text>`);
    }
    for (const t of xTicks) {
      const x = M.l + t.p * PW;
      grid.push(`<line x1="${x.toFixed(1)}" y1="${M.t}" x2="${x.toFixed(1)}" y2="${M.t + PH}"
        stroke="var(--line)" stroke-width="1" fill="none" opacity="0.45"/>`);
      grid.push(`<text x="${x.toFixed(1)}" y="${M.t + PH + 18}" text-anchor="middle"
        font-size="11" fill="var(--muted)" font-family="var(--mono)">${t.label}</text>`);
    }
    grid.push(`<text x="${M.l + PW / 2}" y="${H - 6}" text-anchor="middle" font-size="11"
      fill="var(--muted)">${xLabel}</text>`);
    grid.push(`<text x="14" y="${M.t + PH / 2}" text-anchor="middle" font-size="11"
      fill="var(--muted)" transform="rotate(-90 14 ${M.t + PH / 2})">${yLabel}</text>`);
    return grid.join('');
  }

  const dot = (x, y, label, align) => `
    <circle cx="${x.toFixed(1)}" cy="${y.toFixed(1)}" r="4" fill="var(--accent)"/>
    <text x="${(x + (align === 'left' ? -9 : 9)).toFixed(1)}" y="${(y - 9).toFixed(1)}"
      text-anchor="${align === 'left' ? 'end' : 'start'}" font-size="11.5"
      fill="var(--text)" font-family="var(--mono)">${label}</text>`;

  const svg = (inner, title) => `
    <figure class="ac-fig">
      <svg viewBox="0 0 ${W} ${H}" role="img" aria-label="${title}"
        xmlns="http://www.w3.org/2000/svg">${inner}</svg>
      <figcaption>${title}</figcaption>
    </figure>`;

  /* ------------------------------------------------- impermanent loss ------ */

  /**
   * IL against the price ratio, sampled from LP.analyze.ilV2 on a log x-axis.
   *
   * Log scale on purpose: the function is symmetric in log space -- IL(r) equals IL(1/r) -- and
   * a linear axis hides that, which is the single most useful thing about the curve.
   */
  function impermanentLoss() {
    const il = (r) => (window.LP && LP.analyze) ? LP.analyze.ilV2(r)
      : (2 * Math.sqrt(r)) / (1 + r) - 1;

    const rMin = 0.2, rMax = 5;
    const lx = (r) => (Math.log(r) - Math.log(rMin)) / (Math.log(rMax) - Math.log(rMin));
    const yMin = -0.26;                                   // a touch below IL(5)
    const py = (v) => (v - yMin) / (0 - yMin);

    const pts = [];
    for (let i = 0; i <= 160; i++) {
      const r = Math.exp(Math.log(rMin) + (i / 160) * (Math.log(rMax) - Math.log(rMin)));
      pts.push([M.l + lx(r) * PW, M.t + PH - py(il(r)) * PH]);
    }
    const path = pts.map((p, i) => (i ? 'L' : 'M') + p[0].toFixed(1) + ' ' + p[1].toFixed(1)).join(' ');
    const area = path + ` L${M.l + PW} ${M.t + PH} L${M.l} ${M.t + PH} Z`;

    // The two values the prose quotes, placed by evaluating the function.
    const marks = [2, 4].map((r) => {
      const v = il(r);
      return dot(M.l + lx(r) * PW, M.t + PH - py(v) * PH,
        `${r}× → ${fmt(v * 100, 2)}%`, r === 4 ? 'left' : 'right');
    }).join('');

    // IL(r) = IL(1/r): show the mirror of 2x at 0.5x to make the symmetry visible.
    const half = il(0.5);
    const mirror = dot(M.l + lx(0.5) * PW, M.t + PH - py(half) * PH,
      `0.5× → ${fmt(half * 100, 2)}%`, 'right');

    return svg(
      frame({
        xTicks: [0.25, 0.5, 1, 2, 4].map((r) => ({ p: lx(r), label: r + '×' })),
        yTicks: [0, -0.05, -0.10, -0.15, -0.20, -0.25]
          .map((v) => ({ p: py(v), label: fmt(v * 100, 0) + '%' })),
        xLabel: 'price ratio, relative to when you entered (log scale)',
        yLabel: 'loss vs holding'
      }) +
      `<path d="${area}" fill="var(--bad)" opacity="0.10"/>` +
      `<path d="${path}" fill="none" stroke="var(--bad)" stroke-width="2.5"/>` +
      `<line x1="${M.l + lx(1) * PW}" y1="${M.t}" x2="${M.l + lx(1) * PW}" y2="${M.t + PH}"
        stroke="var(--muted)" stroke-dasharray="3 3" stroke-width="1" fill="none"/>` +
      marks + mirror,
      'Impermanent loss against holding. The curve is symmetric in log space: a halving costs ' +
      'exactly what a doubling costs.');
  }

  /* ------------------------------------------------------- the cost curve -- */

  /**
   * Why a position can be too small to be worth opening.
   *
   * Two costs pulling opposite ways as a share of the position: gas is fixed so it falls like
   * 1/size, slippage is roughly proportional to how much of the pool you are so it rises. Their
   * sum is a U, and the floor is the smallest position that clears a given return.
   */
  function costCurve(opts) {
    opts = opts || {};
    const gasUsd = opts.gasUsd || 4;          // Ethereum-ish, where the effect is visible
    const poolUsd = opts.poolUsd || 2_000_000;

    const sMin = 50, sMax = 200000;
    const lx = (s) => (Math.log(s) - Math.log(sMin)) / (Math.log(sMax) - Math.log(sMin));

    const gasPct = (s) => (gasUsd * 2) / s * 100;
    // Round-trip slippage on a constant-product curve: both legs, each ~ size/pool.
    const slipPct = (s) => (s / poolUsd) * 2 * 100;
    const total = (s) => gasPct(s) + slipPct(s);

    const yMax = 12;
    const py = (v) => Math.max(0, Math.min(1, v / yMax));

    const series = (f, stroke, width, dash) => {
      const pts = [];
      for (let i = 0; i <= 160; i++) {
        const s = Math.exp(Math.log(sMin) + (i / 160) * (Math.log(sMax) - Math.log(sMin)));
        const v = f(s);
        if (v > yMax) continue;
        pts.push([M.l + lx(s) * PW, M.t + PH - py(v) * PH]);
      }
      if (!pts.length) return '';
      return `<path d="${pts.map((p, i) => (i ? 'L' : 'M') + p[0].toFixed(1) + ' ' + p[1].toFixed(1)).join(' ')}"
        fill="none" stroke="${stroke}" stroke-width="${width}"
        ${dash ? 'stroke-dasharray="4 3"' : ''}/>`;
    };

    // The minimum of the total curve, found by sampling the same function that is drawn.
    let best = null;
    for (let i = 0; i <= 400; i++) {
      const s = Math.exp(Math.log(sMin) + (i / 400) * (Math.log(sMax) - Math.log(sMin)));
      const v = total(s);
      if (!best || v < best.v) best = { s, v };
    }

    const legend = `
      <g font-size="11" font-family="var(--mono)">
        <line x1="${M.l + 8}" y1="${M.t + 12}" x2="${M.l + 30}" y2="${M.t + 12}"
          stroke="var(--weak)" stroke-width="2" stroke-dasharray="4 3" fill="none"/>
        <text x="${M.l + 36}" y="${M.t + 16}" fill="var(--muted)">gas, fixed</text>
        <line x1="${M.l + 8}" y1="${M.t + 30}" x2="${M.l + 30}" y2="${M.t + 30}"
          stroke="var(--accent)" stroke-width="2" stroke-dasharray="4 3" fill="none"/>
        <text x="${M.l + 36}" y="${M.t + 34}" fill="var(--muted)">slippage, grows</text>
        <line x1="${M.l + 8}" y1="${M.t + 48}" x2="${M.l + 30}" y2="${M.t + 48}"
          stroke="var(--bad)" stroke-width="2.5" fill="none"/>
        <text x="${M.l + 36}" y="${M.t + 52}" fill="var(--muted)">total round trip</text>
      </g>`;

    return svg(
      frame({
        xTicks: [100, 1000, 10000, 100000].map((s) => ({
          p: lx(s), label: s >= 1000 ? '$' + (s / 1000) + 'k' : '$' + s })),
        yTicks: [0, 3, 6, 9, 12].map((v) => ({ p: py(v), label: v + '%' })),
        xLabel: 'position size (log scale)',
        yLabel: 'cost of a round trip'
      }) +
      series(gasPct, 'var(--weak)', 2, true) +
      series(slipPct, 'var(--accent)', 2, true) +
      series(total, 'var(--bad)', 2.5, false) +
      dot(M.l + lx(best.s) * PW, M.t + PH - py(best.v) * PH,
        `cheapest near $${Math.round(best.s / 100) * 100}`, 'right') +
      legend,
      `Round-trip cost as a share of the position, at $${gasUsd} of gas into a ` +
      `$${(poolUsd / 1e6).toFixed(0)}M pool. Small positions are eaten by gas; large ones by ` +
      `slippage.`);
  }

  /* ------------------------------------------- concentrated range width ---- */

  /**
   * Capital efficiency against range width, from LP.analyze.capitalEfficiency.
   *
   * The marked point is the fact the chapter states: a geometric range four times wide gives
   * exactly 2x. It is placed by evaluating the function at pa = P/2, pb = 2P, not by eye.
   */
  function rangeEfficiency() {
    const eff = (P, pa, pb) => (window.LP && LP.analyze)
      ? LP.analyze.capitalEfficiency(P, pa, pb)
      : 1 / (1 - (Math.sqrt(P / pb) + Math.sqrt(pa / P)) / 2);

    const P = 1;
    /*
     * m is the multiplier on each side: the range runs from P/m to P*m, which is the convention
     * analyze.js documents and its test asserts. Worth being explicit, because "a 4x range" is
     * ambiguous -- it can mean m = 4 (a quarter of the price to four times it, a 16x span) or a
     * 4x span. The first draft of this figure plotted m and labelled the axis with the span,
     * which put the marked point in the wrong place.
     */
    const kMin = 1.05, kMax = 10;
    const lx = (k) => (Math.log(k) - Math.log(kMin)) / (Math.log(kMax) - Math.log(kMin));
    const yMax = 12;
    const py = (v) => Math.max(0, Math.min(1, v / yMax));

    const pts = [];
    for (let i = 0; i <= 200; i++) {
      const k = Math.exp(Math.log(kMin) + (i / 200) * (Math.log(kMax) - Math.log(kMin)));
      const v = eff(P, P / k, P * k);
      if (!(v > 0) || v > yMax) continue;
      pts.push([M.l + lx(k) * PW, M.t + PH - py(v) * PH]);
    }
    const path = pts.map((p, i) => (i ? 'L' : 'M') + p[0].toFixed(1) + ' ' + p[1].toFixed(1)).join(' ');

    // m = 4 is the case the chapters quote: P/4 to 4P gives exactly 2x. Evaluated, not placed.
    const k2 = 4;
    const v2 = eff(P, P / k2, P * k2);

    return svg(
      frame({
        xTicks: [1.25, 2, 4, 8].map((k) => ({ p: lx(k), label: 'P/' + k + '–' + k + 'P' })),
        yTicks: [0, 3, 6, 9, 12].map((v) => ({ p: py(v), label: v + '×' })),
        xLabel: 'range bounds, as a multiple either side of the price (log scale)',
        yLabel: 'capital efficiency'
      }) +
      `<path d="${path}" fill="none" stroke="var(--good)" stroke-width="2.5"/>` +
      dot(M.l + lx(k2) * PW, M.t + PH - py(v2) * PH,
        `P/4–4P → ${fmt(v2, 2)}×`, 'right'),
      'Capital efficiency against range bounds. Narrower earns more per dollar while in range — ' +
      'and leaves range sooner. A range from a quarter of the price to four times it is exactly ' +
      'twice as efficient as full range.');
  }

  return { impermanentLoss, costCurve, rangeEfficiency };
})();
